import { randomBytes } from "node:crypto";
import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { parseEnv } from "node:util";
import { CliError, CliUsageError } from "./cli/errors.js";
import { describeError, unknownErrorCode } from "./describe-error.js";
import { ensureEnvLocalGitignored, upsertEnvFile } from "./env-file.js";
import { runProgram } from "./run-program.js";
import { openTunnelProcess } from "./tunnel-process.js";
/** Bot Framework's local messaging port. The public dev tunnel host embeds it. */
export const DEVTUNNEL_PORT = 3978;
/** Saved in `<dir>/.env.local` so the next start reuses the same tunnel. */
export const DEVTUNNEL_ID_KEY = "TEAMS_DEVTUNNEL_ID";
export const DEVTUNNEL_INSTALL_URL = "https://learn.microsoft.com/azure/developer/dev-tunnels/get-started";
const DEVTUNNEL_INSTALL_HINT = `Install devtunnel from ${DEVTUNNEL_INSTALL_URL}`;
const DEVTUNNEL_LOGIN_HINT = "Run `devtunnel user login`, or `devtunnel user login -g` for a GitHub account.";
const DEVTUNNEL_COMMAND_TIMEOUT_MS = 30_000;
const TUNNEL_ID_PATTERN = /^[a-z0-9][a-z0-9-]*(\.[a-z0-9]+)?$/i;
const DEVTUNNEL_HOST = /https:\/\/[a-z0-9.-]+\.devtunnels\.ms/gi;
export function parseTeamsTunnelChoice(flags) {
    const tunnel = flags.tunnel ?? "cloudflared";
    if (tunnel !== "cloudflared" && tunnel !== "devtunnel") {
        throw new CliUsageError(`--tunnel must be cloudflared or devtunnel (got ${JSON.stringify(tunnel)})`);
    }
    if (flags.tunnelId !== undefined && tunnel !== "devtunnel") {
        throw new CliUsageError("--tunnel-id requires --tunnel devtunnel.");
    }
    if (tunnel === "cloudflared") {
        return { kind: "cloudflared" };
    }
    if (flags.tunnelId !== undefined && !TUNNEL_ID_PATTERN.test(flags.tunnelId)) {
        throw new CliUsageError(`--tunnel-id must be a dev tunnel id such as my-bot (got ${JSON.stringify(flags.tunnelId)})`);
    }
    return { kind: "devtunnel", tunnelId: flags.tunnelId };
}
export function teamsTunnelChoiceFromFlags(values, options) {
    const choice = parseTeamsTunnelChoice({
        tunnel: typeof values.tunnel === "string" ? values.tunnel : undefined,
        tunnelId: typeof values["tunnel-id"] === "string" ? values["tunnel-id"] : undefined,
    });
    if (choice.kind === "devtunnel" && options.agentPort === DEVTUNNEL_PORT) {
        throw new CliUsageError(`--port ${DEVTUNNEL_PORT} is the dev tunnel's local port. Pass another --port.`);
    }
    return choice;
}
function devtunnelMissing() {
    return new CliError("devtunnel is not installed (not found on PATH).", {
        code: "failed_precondition",
        hint: DEVTUNNEL_INSTALL_HINT,
    });
}
function devtunnelStopped() {
    return new CliError("the dev tunnel setup was stopped.", { code: "aborted" });
}
function throwIfStopped(signal) {
    if (signal.aborted) {
        throw devtunnelStopped();
    }
}
function envString(parsed, key) {
    const value = Object.getOwnPropertyDescriptor(parsed, key)?.value;
    return typeof value === "string" && value !== "" ? value : undefined;
}
async function readSavedDevTunnelId(dir) {
    let text;
    try {
        text = await readFile(join(dir, ".env.local"), "utf8");
    }
    catch (error) {
        if (unknownErrorCode(error) === "ENOENT") {
            return undefined;
        }
        throw error;
    }
    return envString(parseEnv(text), DEVTUNNEL_ID_KEY);
}
function newDevTunnelId() {
    return `agent-sdk-${randomBytes(4).toString("hex")}`;
}
function loggedIn(result) {
    return `${result.stdout}\n${result.stderr}`
        .split(/\r?\n/)
        .some((line) => line.startsWith("Logged in as "));
}
function commandFailed(args, result) {
    const detail = (result.stderr.trim() || result.stdout.trim()).split(/\r?\n/, 1)[0] ?? "";
    const suffix = detail === "" ? "" : ` ${detail}`;
    return new CliError(`devtunnel ${args.join(" ")} failed (exit ${result.code ?? "null"}).${suffix}`);
}
function execDevtunnel(args, signal) {
    return runProgram("devtunnel", args, {
        timeoutMs: DEVTUNNEL_COMMAND_TIMEOUT_MS,
        signal,
    });
}
async function runDevtunnel(exec, args, signal) {
    throwIfStopped(signal);
    try {
        const result = await exec(args);
        throwIfStopped(signal);
        if (result.timedOut === true) {
            throw new CliError(`devtunnel ${args.join(" ")} did not answer within ${DEVTUNNEL_COMMAND_TIMEOUT_MS / 1000} s.`);
        }
        return result;
    }
    catch (error) {
        if (signal.aborted) {
            throw devtunnelStopped();
        }
        if (error instanceof CliError) {
            throw error;
        }
        if (unknownErrorCode(error) === "ENOENT") {
            throw devtunnelMissing();
        }
        throw new CliError(`could not run devtunnel: ${describeError(error)}`, {
            hint: DEVTUNNEL_INSTALL_HINT,
        });
    }
}
export async function ensureDevTunnel(input) {
    const port = input.port ?? DEVTUNNEL_PORT;
    const exec = input.exec ?? ((args) => execDevtunnel(args, input.signal));
    const login = await runDevtunnel(exec, ["user", "show"], input.signal);
    if (login.code !== 0 || !loggedIn(login)) {
        throw new CliError("devtunnel is not logged in.", {
            code: "failed_precondition",
            hint: DEVTUNNEL_LOGIN_HINT,
        });
    }
    const saved = await readSavedDevTunnelId(input.dir);
    const tunnelId = input.tunnelId ?? saved ?? newDevTunnelId();
    throwIfStopped(input.signal);
    // Persist before create so a crash after create retries this id.
    if (tunnelId !== saved) {
        await upsertEnvFile(join(input.dir, ".env.local"), [
            { key: DEVTUNNEL_ID_KEY, value: tunnelId },
        ]);
    }
    await ensureEnvLocalGitignored(input.dir);
    const shown = await runDevtunnel(exec, ["show", tunnelId], input.signal);
    let created = false;
    if (shown.code !== 0) {
        const createArgs = ["create", tunnelId, "--allow-anonymous"];
        const made = await runDevtunnel(exec, createArgs, input.signal);
        if (made.code !== 0) {
            throw commandFailed(createArgs, made);
        }
        created = true;
    }
    const portFlag = ["-p", String(port)];
    const portShown = await runDevtunnel(exec, ["port", "show", tunnelId, ...portFlag], input.signal);
    if (portShown.code !== 0) {
        const createArgs = ["port", "create", tunnelId, ...portFlag, "--protocol", "http"];
        const added = await runDevtunnel(exec, createArgs, input.signal);
        if (added.code !== 0) {
            throw commandFailed(createArgs, added);
        }
    }
    return { tunnelId, port, created };
}
/**
 * The public origin for `port` on one line of `devtunnel host` output.
 * `devtunnel host <id>` publishes every port on the tunnel, so a line that
 * names another port throws: that port would bypass the Teams path proxy.
 */
export function parseDevTunnelUrl(line, port) {
    let found;
    for (const match of line.matchAll(DEVTUNNEL_HOST)) {
        const end = (match.index ?? 0) + match[0].length;
        const next = line[end];
        if (next !== undefined && /[a-z0-9.-]/i.test(next)) {
            continue;
        }
        const url = new URL(match[0]);
        const label = url.hostname.split(".")[0]?.toLowerCase() ?? "";
        const hosted = /-(\d+)(-inspect)?$/.exec(label);
        if (hosted === null) {
            continue;
        }
        if (Number(hosted[1]) !== port) {
            throw new CliError(`the dev tunnel also publishes port ${hosted[1]} at ${url.origin}, outside the Teams messaging paths.`, {
                code: "failed_precondition",
                hint: `Remove it with \`devtunnel port delete <tunnel-id> -p ${hosted[1]}\`, or pass another --tunnel-id.`,
            });
        }
        if (hosted[2] === undefined) {
            found ??= url.origin;
        }
    }
    return found;
}
export async function openDevTunnel(input) {
    return openTunnelProcess({
        command: "devtunnel",
        args: ["host", input.tunnelId],
        signal: input.signal,
        spawnImpl: input.spawnImpl,
        timeoutMs: input.timeoutMs,
        parseUrl: (line) => parseDevTunnelUrl(line, input.port),
        program: "devtunnel",
        installHint: DEVTUNNEL_INSTALL_HINT,
        warn: input.warn ?? ((text) => void process.stderr.write(`warning: Teams tunnel: ${text}`)),
    });
}
